```tsx
import { useId } from "react";
import "./SettingsToggleRow.css";

export interface SettingsToggleRowProps {
  label: string;
  hint: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
}

export function SettingsToggleRow({
  label,
  hint,
  checked,
  onChange,
}: SettingsToggleRowProps) {
  const labelId = useId();
  const hintId = useId();

  return (
    <div className="settings-toggle-row">
      <div className="settings-toggle-row__text">
        <span id={labelId} className="settings-toggle-row__label">
          {label}
        </span>
        <span id={hintId} className="settings-toggle-row__hint">
          {hint}
        </span>
      </div>
      <button
        type="button"
        role="switch"
        aria-checked={checked}
        aria-labelledby={labelId}
        aria-describedby={hintId}
        data-checked={checked}
        className="settings-toggle-row__switch"
        onClick={() => onChange(!checked)}
      >
        <span className="settings-toggle-row__thumb" aria-hidden="true" />
      </button>
    </div>
  );
}
```

