/* Theme tokens. Day is the default; night applies via [data-theme="night"]
   on an ancestor, or via prefers-color-scheme when no theme is set. */
.settings-toggle-row {
  --str-label: #1f2a27;
  --str-hint: #5d6b66;
  --str-track-off: #d3dbd7;
  --str-track-on: #3f7a66;
  --str-thumb: #ffffff;
  --str-focus: #2f6f5a;
  --str-divider: rgba(31, 42, 39, 0.1);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="day"]) .settings-toggle-row {
    --str-label: #e6ece9;
    --str-hint: #98a6a0;
    --str-track-off: #3a4642;
    --str-track-on: #6fb39b;
    --str-thumb: #101614;
    --str-focus: #8fd0b6;
    --str-divider: rgba(230, 236, 233, 0.08);
  }
}

[data-theme="night"] .settings-toggle-row {
  --str-label: #e6ece9;
  --str-hint: #98a6a0;
  --str-track-off: #3a4642;
  --str-track-on: #6fb39b;
  --str-thumb: #101614;
  --str-focus: #8fd0b6;
  --str-divider: rgba(230, 236, 233, 0.08);
}

.settings-toggle-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
  padding: 0.875rem 0;
  border-bottom: 1px solid var(--str-divider);
  font-family: inherit;
}

.settings-toggle-row__text {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  min-width: 0;
}

.settings-toggle-row__label {
  font-size: 1rem;
  font-weight: 500;
  color: var(--str-label);
  line-height: 1.3;
}

.settings-toggle-row__hint {
  font-size: 0.875rem;
  color: var(--str-hint);
  line-height: 1.4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.settings-toggle-row__switch {
  position: relative;
  flex: 0 0 auto;
  width: 2.75rem;
  height: 1.5rem;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: var(--str-track-off);
  cursor: pointer;
  transition: background-color 180ms ease;
}

.settings-toggle-row__switch[data-checked="true"] {
  background: var(--str-track-on);
}

.settings-toggle-row__switch:focus-visible {
  outline: 2px solid var(--str-focus);
  outline-offset: 3px;
}

.settings-toggle-row__thumb {
  position: absolute;
  top: 0.1875rem;
  left: 0.1875rem;
  width: 1.125rem;
  height: 1.125rem;
  border-radius: 50%;
  background: var(--str-thumb);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.2);
  transition: transform 180ms ease;
}

.settings-toggle-row__switch[data-checked="true"] .settings-toggle-row__thumb {
  transform: translateX(1.25rem);
}

@media (prefers-reduced-motion: reduce) {
  .settings-toggle-row__switch,
  .settings-toggle-row__thumb {
    transition: none;
  }
}
